function Page_PopUpGiftStickerView:OnOpen()
    self.class.super.OnOpen(self)
	print("Page_PopUpGiftStickerView")
    CommonHelper:GetComponentSetUITexture("roleBg", self.gameObject, self.data.config.spokespersonicon .. ".png", self:GetUIModuleID())
