        CommonHelper:SetText("###ContentText1", self.gameObject, CommonHelper:GetTempStr_Default(self.data.contentTable[1]))
        CommonHelper:SetText("###ContentText2", self.gameObject, CommonHelper:GetTempStr_Default(self.data.contentTable[2]))
        CommonHelper:SetText("###ContentText4", self.gameObject, CommonHelper:GetTempStr_Default(self.data.contentTable[4]))
    end
    local chargecfg = CommonHelper:GetChargeCfgByAreaAndItemId(self.data.config.C_ID)
    CommonHelper:SetText("PurchaseBtn/###priceText", self.gameObject, chargecfg.pricename)
    --local PurchaseBtn= UIUtil.GetChild("PurchaseBtn",self.gameObject)
    --CommonHelper:SetBtnIsRmbOrToken( self.PurchaseBtn,chargecfg)
    self:CountDownTime()
end
function Page_PopUpGiftStickerView:CountDownTime()
    if self.cs_countdown == nil then
        self.cs_countdown = cs_coroutine.start(function()
            while self.data and self.data:IsActive() do
                local timestr =CommonHelper:GetTempStr_Default(self.data.contentTable[3], self:GetDataTimeString())
                CommonHelper:SetText("###ContentText3", self.gameObject, timestr)
                coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))
            end
            UINotify:Get():SendNotification(UINotifyEvent.PopUpGiftView_Refresh)
        end)
    end
end

function Page_PopUpGiftStickerView:OnClose()
    if self.cs_countdown ~= nil then
        cs_coroutine.stop(self.cs_countdown)
        self.cs_countdown = nil
    end
end